// Déplacement + regard, sans arme — prefab par défaut « FPS — déplacement ».
var LOOK_SENSITIVITY = 0.0022;
var SPEED = 6;
var SPEED_SPRINT = 9;
var JUMP = 8;
var GRAVITY = 22;
var PITCH_MAX = 1.45;

var yaw = 0, pitch = 0;
var cam = null;

function start(api){
  cam = api.find('Camera');
  var q = api.me.quaternion;
  yaw = Math.atan2(2 * (q.w * q.y + q.x * q.z), 1 - 2 * (q.y * q.y + q.x * q.x));
  api.me.rotation.set(0, yaw, 0);
  api.lockMouse(true);
}

function update(api){
  if(!api.mouseLocked() && api.click(0)) api.lockMouse(true);

  var md = api.mouseDelta();
  yaw -= md.x * LOOK_SENSITIVITY;
  pitch = Math.max(-PITCH_MAX, Math.min(PITCH_MAX, pitch - md.y * LOOK_SENSITIVITY));
  api.me.rotation.y = yaw;
  if(cam) cam.rotation.x = -pitch;

  var sprinting = api.action('sprint');
  api.moveCharacter({
    speed: sprinting ? SPEED_SPRINT : SPEED,
    jump: JUMP,
    gravity: GRAVITY,
    tagGround: 'ground',
    yaw: yaw
  });
}

